grid=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
S={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v}
len(S), sorted(S)

placements=[]
for r in range(3):
 for c in range(6):
  cells={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if cells<=S: placements.append(('Q',r,c,cells))
  for missing in cells:
   sh=cells-{missing}
   if sh<=S: placements.append(('L'+str((missing[0]-r,missing[1]-c)),r,c,sh))
bycell={p:set() for p in S}
for i,p in enumerate(placements):
 for x in p[3]:bycell[x].add(i)
sol=[]
def dfs(rem, chosen):
 if not rem:
  sol.append(chosen);return
 x=min(rem,key=lambda z:sum(placements[i][3]<=rem for i in bycell[z]))
 for i in bycell[x]:
  sh=placements[i][3]
  if sh<=rem: dfs(rem-sh,chosen+[i])
dfs(S,[])
len(sol)
